"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["66134"],{97003(e){e.exports=JSON.parse('{"id":"F477","slug":"token-nav-and-fees","name":"Tokenized Asset: Value per Token and Cost of Access","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Tokenization of real-world assets","level":"Intermediate","aliases":["tokenization of real-world assets","fractional ownership","NAV per token","token premium","RWA tokens"],"formula":{"latex":"NAV_{tok}=\\\\frac{V(1-f\\\\,T)}{N},\\\\quad P=NAV_{tok}(1+\\\\delta)","also":[],"text":"Value per token = (asset value - annual fees x years) / tokens issued; Premium or discount = market price / value per token - 1; Cost to buy and sell = 2 x trading fee + bid-ask spread; Minimum investment = value per token"},"symbols":[{"symbol":"V","meaning":"Value of the underlying asset (a building, a bond, a fund)","unit":"money"},{"symbol":"N","meaning":"Tokens issued","unit":"count"},{"symbol":"f, T","meaning":"Yearly structure and custody fee and years held","unit":"percent, years"},{"symbol":"delta","meaning":"Premium (or discount) of the token price to its underlying value","unit":"percent"}],"when_to_use":"Use it to check what a token is really worth. A token represents a legal claim to an asset; its price can differ from the value of the asset if few people trade it. Fees, the law that gives the claim force and the chance to redeem determine whether the token tracks the asset. Fractions lower the minimum ticket but do not by themselves create liquidity.","worked_example":{"problem":"A 50m property is split into 5m tokens. Annual structure and custody fees are 0.45%. The token trades at a 4% discount, and trading costs 0.35% each way.","inputs":{"v":50000000,"n":5000000,"f":0.45,"t":1,"d":-4,"tf":0.35},"steps":[{"label":"Value per token","working":"50,000,000 x (1-0.0045 x 1) / 5,000,000","value":"9.96"},{"label":"Market price = value x (1 + premium)","working":"9.955 x (1+-0.04)","value":"9.56"},{"label":"Round-trip trading cost","working":"2 x 0.0035","value":"0.70%"},{"label":"Gain if price returns to value (before fees)","working":"9.955 / 9.5568-1","value":"4.17%"}],"answer":"Each token is worth 9.96 after one year of fees. At a 4% discount the price is 9.56. A round trip costs 0.70% in trading fees; buying at the discount and selling at the value per token would earn 4.17% before fees."},"calculator":{"available":true,"inputs":[{"id":"v","label":"Underlying asset value","unit":"money","type":"number","default":50000000,"hint":""},{"id":"n","label":"Tokens issued","unit":"count","type":"number","default":5000000,"hint":""},{"id":"f","label":"Annual fees","unit":"%","type":"number","default":0.45,"hint":""},{"id":"t","label":"Years held","unit":"years","type":"number","default":1,"hint":"","min":0},{"id":"d","label":"Premium (negative = discount)","unit":"%","type":"number","default":-4,"hint":""},{"id":"tf","label":"Trading fee each way","unit":"%","type":"number","default":0.35,"hint":""}],"checks":[{"expr":"n>0 and v>0","message":"Asset value and token count must be above zero."}],"steps":[{"id":"nav","label":"Value per token","expr":"v*(1-f*t)/n","format":"money"},{"id":"px","label":"Market price = value x (1 + premium)","expr":"nav*(1+d)","format":"money"},{"id":"rt","label":"Round-trip trading cost","expr":"2*tf","format":"pct2"},{"id":"gain","label":"Gain if price returns to value (before fees)","expr":"nav/px-1","format":"pct2"}],"results":["nav","px","rt","gain"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"nav":9.955,"px":9.556799999999999,"rt":0.007,"gain":0.04166666666666674}},"finder":{"finds":"What a token is worth and what trading it costs","needs":"Asset value, tokens, fees, premium or discount"},"related":[{"slug":"illiquidity-discount","name":"Discount for Lack of Marketability (Private Companies)"},{"slug":"etf-premium-tracking","name":"ETF Premium/Discount and Tracking Difference"},{"slug":"crypto-etf-fee-drag","name":"Crypto ETF vs Direct Holding: Fee Drag and Cost"}],"related_ids":["F225","F270","F478"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>N</mi><mi>A</mi><msub><mi>V</mi><mrow><mi>t</mi><mi>o</mi><mi>k</mi></mrow></msub><mo>=</mo><mfrac><mrow><mi>V</mi><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>f</mi><mtext>\u2009</mtext><mi>T</mi><mo stretchy=\\"false\\">)</mo></mrow><mi>N</mi></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>P</mi><mo>=</mo><mi>N</mi><mi>A</mi><msub><mi>V</mi><mrow><mi>t</mi><mi>o</mi><mi>k</mi></mrow></msub><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>\u03B4</mi><mo stretchy=\\"false\\">)</mo></mrow><annotation encoding=\\"application/x-tex\\">NAV_{tok}=\\\\frac{V(1-f\\\\,T)}{N},\\\\quad P=NAV_{tok}(1+\\\\delta)</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"time-weighted-return","name":"Time-Weighted Return"},"next":{"slug":"trade-off-value","name":"Trade-Off Theory Firm Value"},"lesson":null,"total":522}')}}]);